func (s *Scanner) nextClass() (class BreakClass, err error) {
	if s.err != nil {
		return class, s.err
	}
	if s.pos >= len(s.runes) {
		s.err = io.EOF
		return class, s.err
	}
	isFirst := s.pos == 0
	class = s.Resolver(s.runes[s.pos])
	s.pos += 1
	switch class {
	case ClassNL:
		class = ClassBK
	case ClassSP:
		if isFirst {
			class = ClassWJ
		}
	case ClassLF:
		if isFirst {
			class = ClassBK
		}
	}
	return class, err
}

func (s *Scanner) Next() (idx int, action BreakAction, err error) {
	var class BreakClass
	if s.pos == 0 {
		class, err = s.nextClass()
		if err != nil {
			action = BreakMandatory
			return idx, action, err
		}
		s.prevClass = class
		action = BreakProhibited
		return idx, action, err
	}
	idx = s.pos
	class, err = s.nextClass()
	if err != nil {
		action = BreakMandatory
		return idx, action, err
	}
	if !(s.prevClass != ClassBK && (s.prevClass != ClassCR || class == ClassLF)) {
		return idx, action, err
	}
	switch class {
	case ClassBK, ClassLF:
		action = BreakProhibited
		s.prevClass = ClassBK
		return idx, action, err
	case ClassCR:
		action = BreakProhibited
		s.prevClass = ClassCR
		return idx, action, err
	case ClassSP:
		action = BreakProhibited
		return idx, action, err
	}
	action = s.Table.Action(s.prevClass, class)
	switch action {
	case BreakIndirect:
		switch s.prevClass {
		case ClassSP:
			action = BreakIndirect
		default:
			action = BreakProhibited
		}
	case BreakCombiningIndirect:
		switch s.prevClass {
		case ClassSP:
			action = BreakCombiningIndirect
		default:
			action = BreakProhibited
			return idx, action, err
		}
	case BreakCombiningProhibited:
		action = BreakProhibited
		if s.prevClass == ClassSP {
			return idx, action, err
		}
	}
	s.prevClass = class
	return idx, action, err
}
